/* ============================================================
   Minimal JSZip-compatible shim for UnArtifact
   Supports: loadAsync(ArrayBuffer), file(name), file(name, data),
             remove(name), files map, generateAsync({type:'blob'}, cb)
   Backed by the browser-native CompressionStream('deflate-raw').
   MIT.

   Fixes vs. previous revision:
     • remove() now deletes the key from this.files (matches real JSZip).
     • file() returns null for absent/tombstoned keys without crashing.
     • _readEntry() handles data-descriptor entries (flag bit 3) by
       scanning forward for the next PK signature when compSize is 0.
   ============================================================ */
(function (global) {
  'use strict';

  const enc = new TextEncoder();
  const dec = new TextDecoder('utf-8');

  /* ---------------- CRC32 ---------------- */
  const CRC_TABLE = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      t[n] = c >>> 0;
    }
    return t;
  })();

  function crc32(bytes) {
    let c = 0xFFFFFFFF;
    for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xFF] ^ (c >>> 8);
    return (c ^ 0xFFFFFFFF) >>> 0;
  }

  /* ---------------- deflate-raw via CompressionStream ---------------- */
  async function deflateRaw(bytes) {
    const cs = new CompressionStream('deflate-raw');
    const writer = cs.writable.getWriter();
    writer.write(bytes);
    writer.close();
    return new Uint8Array(await new Response(cs.readable).arrayBuffer());
  }

  async function inflateRaw(bytes) {
    const ds = new DecompressionStream('deflate-raw');
    const writer = ds.writable.getWriter();
    writer.write(bytes);
    writer.close();
    return new Uint8Array(await new Response(ds.readable).arrayBuffer());
  }

  /* ---------------- ZIP writer ---------------- */
  function dosTime(d = new Date()) {
    const time = ((d.getHours() & 0x1F) << 11) |
                 ((d.getMinutes() & 0x3F) << 5) |
                 ((d.getSeconds() / 2) & 0x1F);
    const date = (((d.getFullYear() - 1980) & 0x7F) << 9) |
                 (((d.getMonth() + 1) & 0x0F) << 5) |
                 (d.getDate() & 0x1F);
    return { time, date };
  }

  async function writeZip(entries) {
    const parts = [];
    const central = [];
    let offset = 0;
    const { time, date } = dosTime();

    for (const e of entries) {
      const nameBytes = enc.encode(e.name);
      const raw = e.bytes;
      const crc = crc32(raw);
      let method = 0, body = raw, compSize = raw.length;

      if (e.compress && raw.length > 64) {
        try {
          body = await deflateRaw(raw);
          method = 8;
          compSize = body.length;
        } catch {
          method = 0;
          body = raw;
          compSize = raw.length;
        }
      }

      // Local file header
      const lh = new Uint8Array(30 + nameBytes.length);
      const lv = new DataView(lh.buffer);
      lv.setUint32(0, 0x04034b50, true);
      lv.setUint16(4, 20, true);       // version needed
      lv.setUint16(6, 0x0800, true);   // UTF-8 flag
      lv.setUint16(8, method, true);
      lv.setUint16(10, time, true);
      lv.setUint16(12, date, true);
      lv.setUint32(14, crc, true);
      lv.setUint32(18, compSize, true);
      lv.setUint32(22, raw.length, true);
      lv.setUint16(26, nameBytes.length, true);
      lv.setUint16(28, 0, true);
      lh.set(nameBytes, 30);

      parts.push(lh, body);

      // Central directory entry
      const cd = new Uint8Array(46 + nameBytes.length);
      const cv = new DataView(cd.buffer);
      cv.setUint32(0, 0x02014b50, true);
      cv.setUint16(4, 20, true);
      cv.setUint16(6, 20, true);
      cv.setUint16(8, 0x0800, true);
      cv.setUint16(10, method, true);
      cv.setUint16(12, time, true);
      cv.setUint16(14, date, true);
      cv.setUint32(16, crc, true);
      cv.setUint32(20, compSize, true);
      cv.setUint32(24, raw.length, true);
      cv.setUint16(28, nameBytes.length, true);
      cv.setUint16(30, 0, true);
      cv.setUint16(32, 0, true);
      cv.setUint16(34, 0, true);
      cv.setUint16(36, 0, true);
      cv.setUint32(38, 0, true);
      cv.setUint32(42, offset, true);
      cd.set(nameBytes, 46);
      central.push(cd);

      offset += lh.length + body.length;
    }

    const cdBytes = new Uint8Array(central.reduce((n, c) => n + c.length, 0));
    let p = 0;
    for (const c of central) { cdBytes.set(c, p); p += c.length; }

    const eocd = new Uint8Array(22);
    const ev = new DataView(eocd.buffer);
    ev.setUint32(0, 0x06054b50, true);
    ev.setUint16(4, 0, true);
    ev.setUint16(6, 0, true);
    ev.setUint16(8, entries.length, true);
    ev.setUint16(10, entries.length, true);
    ev.setUint32(12, cdBytes.length, true);
    ev.setUint32(16, offset, true);
    ev.setUint16(20, 0, true);

    return [parts, cdBytes, eocd];
  }

  /* ---------------- ZIP reader ---------------- */
  function readZip(buffer) {
    const view = new DataView(buffer);
    const bytes = new Uint8Array(buffer);

    // Locate EOCD (scan backwards for the signature).
    let eocd = -1;
    const minStart = Math.max(0, bytes.length - 22 - 0xFFFF);
    for (let i = bytes.length - 22; i >= minStart; i--) {
      if (view.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
    }
    if (eocd < 0) throw new Error('Not a zip: EOCD not found');

    const count = view.getUint16(eocd + 10, true);
    const cdOffset = view.getUint32(eocd + 16, true);

    const entries = new Map();
    let p = cdOffset;
    for (let i = 0; i < count; i++) {
      if (view.getUint32(p, true) !== 0x02014b50) throw new Error('Bad central directory');
      const flags     = view.getUint16(p + 8, true);
      const method    = view.getUint16(p + 10, true);
      const compSize  = view.getUint32(p + 20, true);
      const uncompSize= view.getUint32(p + 24, true);
      const nameLen   = view.getUint16(p + 28, true);
      const extraLen  = view.getUint16(p + 30, true);
      const commentLen= view.getUint16(p + 32, true);
      const localOff  = view.getUint32(p + 42, true);
      const name = dec.decode(bytes.subarray(p + 46, p + 46 + nameLen));
      entries.set(name, { flags, method, compSize, uncompSize, localOffset: localOff, name });
      p += 46 + nameLen + extraLen + commentLen;
    }

    return { entries, bytes, view };
  }

  /* ---------------- Zip class ---------------- */
  class Zip {
    constructor() {
      this.files = Object.create(null);
      this._source = null;
    }

    async loadAsync(buffer) {
      this._source = readZip(buffer);
      for (const [name, meta] of this._source.entries) {
        this.files[name] = { _meta: meta, _bytes: null };
      }
      return this;
    }

    file(name, data) {
      if (data === undefined) {
        const f = this.files[name];
        if (!f) return null;                 // real JSZip returns null for absent keys
        return makeEntry(this, name, f);
      }
      // set
      this.files[name] = {
        _meta: null,
        _bytes: typeof data === 'string' ? enc.encode(data) : toBytes(data),
      };
      return this;
    }

    remove(name) {
      if (Object.prototype.hasOwnProperty.call(this.files, name)) {
        delete this.files[name];             // real removal, matches JSZip semantics
      }
      return this;
    }

    async generateAsync(opts = {}, onUpdate) {
      const entries = [];
      const names = Object.keys(this.files);
      let i = 0;
      for (const name of names) {
        const f = this.files[name];
        let raw;
        if (f._bytes) raw = f._bytes;
        else if (f._meta) raw = await this._readEntry(f._meta);
        else continue;
        entries.push({ name, bytes: raw, compress: opts.compression === 'DEFLATE' });
        i++;
        if (onUpdate) onUpdate({ percent: (i / names.length) * 100 });
      }

      const [parts, cd, eocd] = await writeZip(entries);
      const blob = new Blob([...parts, cd, eocd], {
        type: opts.mimeType || 'application/zip',
      });

      if (opts.type === 'uint8array') return new Uint8Array(await blob.arrayBuffer());
      if (opts.type === 'arraybuffer') return await blob.arrayBuffer();
      return blob; // 'blob' is what UnArtifact uses
    }

    async _readEntry(meta) {
      const { bytes, view } = this._source;
      const lo = meta.localOffset;
      if (view.getUint32(lo, true) !== 0x04034b50) {
        throw new Error('Bad local header for ' + meta.name);
      }
      const flags    = view.getUint16(lo + 6, true);
      const nameLen  = view.getUint16(lo + 26, true);
      const extraLen = view.getUint16(lo + 28, true);
      const start    = lo + 30 + nameLen + extraLen;

      // If the central directory says 0 bytes (data descriptor case),
      // or the entry is flagged as using a data descriptor, scan forward
      // for the next PK signature.
      let end;
      const useDescriptor = (flags & 0x0008) !== 0 || !meta.compSize;
      if (!useDescriptor) {
        end = start + meta.compSize;
      } else {
        end = start;
        while (end + 4 <= bytes.length) {
          const sig = view.getUint32(end, true);
          if (sig === 0x04034b50 || sig === 0x02014b50 || sig === 0x06054b50) break;
          end++;
        }
      }

      const comp = bytes.subarray(start, end);
      if (meta.method === 0) return comp;
      if (meta.method === 8) return await inflateRaw(comp);
      throw new Error('Unsupported compression method ' + meta.method + ' for ' + meta.name);
    }
  }

  /* ---------------- helpers ---------------- */
  function toBytes(data) {
    if (data instanceof Uint8Array) return data;
    if (data instanceof ArrayBuffer) return new Uint8Array(data);
    if (typeof data === 'string') return enc.encode(data);
    throw new Error('Unsupported entry data type');
  }

  function makeEntry(zip, name, f) {
    return {
      name,
      async async(type) {
        let raw;
        if (f._bytes) raw = f._bytes;
        else if (f._meta) raw = await zip._readEntry(f._meta);
        else raw = new Uint8Array(0);
        if (type === 'string') return dec.decode(raw);
        if (type === 'uint8array') return raw;
        if (type === 'arraybuffer') return raw.buffer.slice(raw.byteOffset, raw.byteOffset + raw.byteLength);
        if (type === 'blob') return new Blob([raw]);
        return raw;
      },
    };
  }

  global.JSZip = {
    loadAsync: async (buf) => new Zip().loadAsync(buf),
  };
})(typeof window !== 'undefined' ? window : self);